// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {FlashGovernanceArbiter} from "../src/FlashGovernanceArbiter.sol";

contract InvMutTest is Test {
    FlashGovernanceArbiter c;
    function setUp() public { c = new FlashGovernanceArbiter(address(this)); }
    function testRegression_property() public {

        vm.startPrank(address(this));
        c.endConfiguration();
        bool ok;
        try c.assertGovernanceApproved(address(this), address(this), false) { ok = true; } catch { ok = false; }
        vm.stopPrank();
        assertTrue(c.configured());
    }
}
